<div class="order-meta"><span class="chip"><?=e(status_label($order))?></span><span><?=e(ucfirst($order['fulfillment']))?> · <?=e(local_time($order['created_at']))?></span></div><h2><?=e($order['shop_name'])?></h2><p class="hint">Order <?=e($order['reference'])?></p><div class="order-items"><?php foreach($items as $item): ?><div class="checkout-item"><span><?=e($item['name'])?> × <?=$item['quantity']?></span><strong><?=money((int)$item['total_paisa'])?></strong></div><?php endforeach ?></div><div class="order-totals"><div class="total-line"><span>Food subtotal</span><strong><?=money((int)$order['subtotal_paisa'])?></strong></div><div class="total-line"><span>Delivery charges<?=$order['fulfillment']==='pickup'?' · Self pickup':''?></span><strong><?=money((int)$order['delivery_fee_paisa'])?></strong></div><div class="total-line grand-total"><span>Total</span><strong><?=money((int)$order['total_paisa'])?></strong></div></div><p><strong><?=$order['fulfillment']==='pickup'?'Pickup location':'Delivery address'?></strong><br><?=nl2br(e($order['fulfillment']==='pickup'?$order['shop_address']:$order['delivery_address']))?></p><p class="hint"><?=$order['fulfillment']==='pickup'?'Pay on pickup.':'Cash on delivery.'?> Contact the shop: <?=e($order['shop_phone'])?></p>
